package kr.or.arte.seal.rights.web;
import kr.or.arte.seal.admin.config.AdminPrincipal;import kr.or.arte.seal.rights.application.*;import kr.or.arte.seal.rights.domain.*;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.UUID;
@Controller @RequestMapping({"/admin/rights","/admin/rights-requests"}) public class RightsRequestController {private final RightsRequestService service;public RightsRequestController(RightsRequestService s){service=s;}
 @GetMapping @PreAuthorize("hasAuthority('RIGHTS_VIEW')") public String list(@RequestParam(required=false)RightsRequestStatus status,@AuthenticationPrincipal AdminPrincipal p,Model m){m.addAttribute("administrator",p);m.addAttribute("items",service.search(p.adminUserId(),status));m.addAttribute("selectedStatus",status);return "admin/rights/list";}
 @GetMapping("/new") @PreAuthorize("hasAuthority('RIGHTS_EDIT')") public String form(){return "admin/rights/form";}
 @PostMapping @PreAuthorize("hasAuthority('RIGHTS_EDIT')") public String create(@RequestParam UUID organizationId,@RequestParam UUID recipientId,@RequestParam(required=false)UUID consentRequestId,@RequestParam RightsRequestType type,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate receivedDate,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate dueDate,@RequestParam String detail,@AuthenticationPrincipal AdminPrincipal p){return "redirect:/admin/rights/"+service.create(organizationId,recipientId,consentRequestId,type,receivedDate,dueDate,detail,p.adminUserId());}
 @GetMapping("/{id}") @PreAuthorize("hasAuthority('RIGHTS_VIEW')") public String detail(@PathVariable UUID id,@AuthenticationPrincipal AdminPrincipal p,Model m){m.addAttribute("administrator",p);m.addAttribute("item",service.require(p.adminUserId(),id));return "admin/rights/detail";}
 @PostMapping("/{id}/verify") @PreAuthorize("hasAuthority('RIGHTS_EDIT')") public String verify(@PathVariable UUID id,@RequestParam String channel,@RequestParam String note,@AuthenticationPrincipal AdminPrincipal p){service.verifyIdentity(p.adminUserId(),id,channel,note);return back(id);}
 @PostMapping("/{id}/review") @PreAuthorize("hasAuthority('RIGHTS_EDIT')") public String review(@PathVariable UUID id,@AuthenticationPrincipal AdminPrincipal p){service.startReview(p.adminUserId(),id);return back(id);}
 @PostMapping("/{id}/decision") @PreAuthorize("hasAuthority('RIGHTS_APPROVE')") public String decide(@PathVariable UUID id,@RequestParam boolean approve,@RequestParam String reason,@AuthenticationPrincipal AdminPrincipal p){service.decide(p.adminUserId(),id,approve,reason);return back(id);}
 @PostMapping("/{id}/complete") @PreAuthorize("hasAuthority('RIGHTS_EDIT')") public String complete(@PathVariable UUID id,@RequestParam String result,@AuthenticationPrincipal AdminPrincipal p){service.complete(p.adminUserId(),id,result);return back(id);}private static String back(UUID id){return "redirect:/admin/rights/"+id;}}
